const tickerMap = {
  bitcoin:'BTC', ethereum:'ETH', litecoin:'LTC', binancecoin:'BNB', ripple:'XRP',
  solana:'SOL', 'the-open-network':'TON', 'avalanche-2':'AVAX', stellar:'XLM',
  tron:'TRX', cardano:'ADA', chainlink:'LINK', uniswap:'UNI', aave:'AAVE',
  'injective-protocol':'INJ', jasmycoin:'JASMY', pepe:'PEPE', 'shiba-inu':'SHIB',
  dogecoin:'DOGE', floki:'FLOKI', notcoin:'NOT', 'book-of-meme':'BOME', bonk:'BONK'
};

const raw = $input.first().json;
const prices = {};
for (const [cgId, data] of Object.entries(raw)) {
  const ticker = tickerMap[cgId];
  if (!ticker) continue;
  const change = Number(data.usd_24h_change ?? 0);
  prices[ticker] = {
    price: data.usd,
    change_24h: Math.round(change * 100) / 100,
    volume: data.usd_24h_vol ?? 0,
    market_cap: data.usd_market_cap ?? 0,
    gold_units: Math.round(Math.abs(change) * 10) / 10,
    direction: change >= 0 ? 'heavier' : 'lighter'
  };
}

const btc = prices.BTC?.change_24h ?? 0;
const eth = prices.ETH?.change_24h ?? 0;
const avg = (btc + eth) / 2;
let market_condition = 'waiting_plains';
if (avg > 0.5) market_condition = 'golden_season';
else if (avg < -0.5) market_condition = 'dark_siege';

return [{ json: { prices, market_condition, fetched_at: new Date().toISOString() } }];

const CLANS = {
  ancients: { name:'Clan of the Ancients', territory:'The Obsidian Citadel', coins:['BTC','ETH','LTC','BNB','XRP'], characters:['Aragorn','Gandalf','Samwise','Elrond','Boromir'] },
  swift: { name:'Clan of the Swift', territory:'The Electric Plains', coins:['SOL','TON','AVAX','XLM','TRX'], characters:['Legolas','Eomer','Eowyn','Faramir','Saruman'] },
  meme_lords: { name:'Clan of Meme Lords', territory:'Kekiston Bazaar', coins:['PEPE','SHIB','DOGE','FLOKI','NOT','BOME','BONK'], characters:['Tom Bombadil','Merry','Pippin','Theoden','Frodo','Bilbo','Gollum'] },
  builders: { name:'Clan of the Builders', territory:'The Forge of Chains', coins:['LINK','UNI','AAVE','INJ','ADA','JASMY'], characters:['Gimli','Galadriel','Treebeard'] }
};

const { prices, market_condition } = $('Normalize Prices & Market Condition').first().json;
const recentClans = $input.all().map(i => i.json.clan);
const allClans = Object.keys(CLANS);

let dominant = null;
outer:
for (const [clanKey, clan] of Object.entries(CLANS)) {
  for (const coin of clan.coins) {
    if (prices[coin] && Math.abs(prices[coin].change_24h) > 12) {
      dominant = clanKey;
      break outer;
    }
  }
}

let selected = dominant;
if (!selected) selected = allClans.find(c => !recentClans.includes(c));
if (!selected) selected = recentClans.length ? recentClans[recentClans.length - 1] : allClans[Math.floor(Math.random()*allClans.length)];

return [{ json: { selected_clan: selected, clan: CLANS[selected], prices, market_condition } }];

const { clan } = $('Select Clan').item.json;
const allStatus = $('Get All Character Status').all().map(i => i.json);

const heavenLines = [];
const heavens = {};
for (const coin of clan.coins) {
  const row = allStatus.find(r => r.coin_ticker === coin);
  if (!row) continue;
  heavens[coin] = { character: row.character_name, gate: row.gate_number, heaven: row.heaven_number, last_price: row.current_price };
  heavenLines.push(`  - ${row.character_name}: ${coin} | Heaven ${row.heaven_number} of Gate ${row.gate_number} | Last price: $${row.current_price}`);
}

return [{ json: { heavens, heaven_lines: heavenLines.join('\n') } }];

const base = 'https://raw.githubusercontent.com/GbadeboMotunrayo/coinor-chronicles/main';
const docs = {
  world_bible: `${base}/docs/WORLD_BIBLE.md`,
  character_voices: `${base}/docs/CHARACTER_VOICES.md`,
  external_realms: `${base}/docs/EXTERNAL_REALMS.md`,
  cosmology: `${base}/docs/COSMOLOGY.md`,
  script_generator: `${base}/prompts/script_generator.md`,
  review_agent: `${base}/prompts/review_agent.md`,
  celebration_episode: `${base}/prompts/celebration_episode.md`
};

const fetched = {};
for (const [key, url] of Object.entries(docs)) {
  try { fetched[key] = await this.helpers.httpRequest({ method: 'GET', url }); }
  catch (e) { fetched[key] = ''; }
}

const style_guide = [fetched.world_bible, fetched.character_voices, fetched.external_realms, fetched.cosmology]
  .filter(Boolean).join('\n\n---\n\n');

return [{ json: { style_guide, ...fetched } }];

const { clan, prices, market_condition, selected_clan } = $('Select Clan').item.json;
const { heaven_lines } = $('Build Heaven Positions & Context').item.json;
const memoryRows = $('Get Story Memory').all();
const memory = memoryRows.length ? memoryRows[0].json : {};
const overrideRows = $('Get Creator Override').all();
const override = overrideRows.length ? overrideRows[0].json : null;

const settingsRows = $('Get Story Settings').all();
const story_count = (settingsRows.length ? Number(settingsRows[0].json.setting_value) : 0) + 1;

const coinLines = clan.coins
  .filter(c => prices[c])
  .map(c => `  - ${c}: $${prices[c].price} | ${prices[c].change_24h}% | ${prices[c].gold_units} gold units ${prices[c].direction}`)
  .join('\n');

const conditionName = { golden_season: 'The Golden Season', dark_siege: 'The Dark Siege', waiting_plains: 'The Waiting Plains' }[market_condition];

const prompt = `SELECTED_CLAN: ${clan.name} — ${clan.territory}
MARKET_CONDITION: ${conditionName}
MARKET_DATA:
${coinLines}
LAST_EPISODE_SUMMARY: ${memory.last_summary || 'The chronicle begins.'}
STORY_DIRECTION: ${memory.story_direction || ''}
CURRENT_HEAVENS:
${heaven_lines}
CREATOR_OVERRIDE: ${override ? override.override_text : 'None — generate naturally from market data'}
STORY_COUNT: ${story_count}

Now write the episode following all rules in the style guide.`;

return [{ json: { prompt, story_count, has_override: !!override, override_id: override ? override.id : null, selected_clan } }];

const reviewText = $json.content[0].text;
const passed = reviewText.toUpperCase().includes('REVIEW RESULT: PASS');
const storyText = $('Anthropic - Generate Story').item.json.content[0].text;
return [{ json: { passed, review_notes: reviewText, story_raw: storyText } }];

const basePrompt = $('Build Story Prompt').item.json.prompt;
const notes = $('Parse Review Result').item.json.review_notes;
const feedback_prompt = `${basePrompt}

## PREVIOUS ATTEMPT FAILED REVIEW:
${notes}

Fix these issues in your next attempt.`;
return [{ json: { feedback_prompt } }];

const reviewText = $json.content[0].text;
const passed = reviewText.toUpperCase().includes('REVIEW RESULT: PASS');
const storyText = $('Anthropic - Regenerate Story').item.json.content[0].text;
return [{ json: { passed, review_notes: reviewText, story_raw: storyText } }];

function esc(s) { return String(s ?? '').replace(/\\/g, '\\\\').replace(/'/g, "\\'"); }
return [{ json: {
  selected_clan: $('Select Clan').item.json.selected_clan,
  error_msg: esc('Story failed review twice: ' + $('Parse Review Result (2nd Pass)').item.json.review_notes)
} }];

const raw = $json.story_raw;
const lines = raw.trim().split('\n');
let title = lines[0].replace(/\*\*/g, '').replace(/\*/g, '').replace(/#/g, '').trim();
if (title.length > 255) title = title.slice(0, 252) + '...';

let story_text = raw;
let scene_notes = '';
if (raw.includes('[SCENE NOTES]')) {
  story_text = raw.slice(0, raw.indexOf('[SCENE NOTES]')).trim();
  scene_notes = raw.slice(raw.indexOf('[SCENE NOTES]'));
}

return [{ json: { title, story_text, scene_notes, is_celebration: false, is_donation: false } }];

// NOTE: set your real donation wallet addresses below before going live.
const wallets = `
**The Fellowship Contribution Scrolls:**
- BTC: \`YOUR_BTC_WALLET_ADDRESS\`
- ETH: \`YOUR_ETH_WALLET_ADDRESS\`
- USDT: \`YOUR_USDT_WALLET_ADDRESS\`
- PEPE: \`YOUR_PEPE_WALLET_ADDRESS\`
- SHIB: \`YOUR_SHIB_WALLET_ADDRESS\`
`;
const item = { ...$json };
item.story_text = item.story_text.replace('[WALLET_PLACEHOLDER]', wallets);
item.is_donation = true;
return [{ json: item }];

const GATES = {
  BTC:{gate1:100000,gate2:1000000,gate3:10000000}, ETH:{gate1:10000,gate2:100000,gate3:1000000},
  SOL:{gate1:1000,gate2:10000,gate3:100000}, XRP:{gate1:100,gate2:1000,gate3:10000},
  BNB:{gate1:10000,gate2:100000,gate3:1000000}, LTC:{gate1:1000,gate2:10000,gate3:100000},
  TON:{gate1:10,gate2:100,gate3:1000}, AVAX:{gate1:500,gate2:5000,gate3:50000},
  XLM:{gate1:5,gate2:50,gate3:500}, TRX:{gate1:1,gate2:10,gate3:100},
  ADA:{gate1:10,gate2:100,gate3:1000}, JASMY:{gate1:1,gate2:10,gate3:100},
  LINK:{gate1:1000,gate2:10000,gate3:100000}, UNI:{gate1:100,gate2:1000,gate3:10000},
  AAVE:{gate1:10000,gate2:100000,gate3:1000000}, INJ:{gate1:1000,gate2:10000,gate3:100000},
  PEPE:{gate1:1,gate2:10,gate3:100}, SHIB:{gate1:0.001,gate2:0.01,gate3:0.1},
  DOGE:{gate1:10,gate2:100,gate3:1000}, FLOKI:{gate1:1,gate2:10,gate3:100},
  NOT:{gate1:0.1,gate2:1,gate3:10}, BOME:{gate1:0.1,gate2:1,gate3:10}, BONK:{gate1:1,gate2:10,gate3:100}
};

const { clan, prices } = $('Select Clan').item.json;
const allStatus = $('Get All Character Status').all().map(i => i.json);
const existing = $input.all().map(i => i.json);

const already = (coin, type, value) => existing.some(m => m.coin_ticker === coin && m.milestone_type === type && Number(m.milestone_value) === Number(value));

const crossed = [];
for (const coin of clan.coins) {
  const gates = GATES[coin];
  const status = allStatus.find(r => r.coin_ticker === coin);
  if (!gates || !status || !prices[coin]) continue;

  const currentPrice = prices[coin].price;
  const gateKey = 'gate' + status.gate_number;
  const gatePrice = gates[gateKey];
  if (!gatePrice) continue;

  if (currentPrice >= gatePrice && !already(coin, 'gate', status.gate_number)) {
    crossed.push({ coin, type: 'gate', value: status.gate_number, price: currentPrice, character: status.character_name });
  }

  const prevGateKey = 'gate' + (status.gate_number - 1);
  const prevGatePrice = status.gate_number > 1 ? (gates[prevGateKey] || 0) : 0;
  const gap = gatePrice - prevGatePrice;
  const heavenThreshold = prevGatePrice + (gap / 10) * status.heaven_number;

  if (currentPrice >= heavenThreshold && !already(coin, 'heaven', status.heaven_number)) {
    crossed.push({ coin, type: 'heaven', value: status.heaven_number, price: currentPrice, character: status.character_name });
  }
}

return [{ json: { is_celebration: crossed.length > 0, milestones_crossed: crossed, milestone: crossed[0] || null } }];

const m = $('Check Milestones').item.json.milestone;
const prompt = `MILESTONE_TYPE: ${m.type.toUpperCase()}_CROSSING
CHARACTER: ${m.character}
COIN: ${m.coin}
MILESTONE: ${m.type.charAt(0).toUpperCase() + m.type.slice(1)} ${m.value}
PRICE_AT_MILESTONE: $${m.price}
DATE: ${new Date().toISOString().slice(0,10)}

Write a full celebration episode for this milestone, following the celebration_episode.md structure exactly.`;
return [{ json: { celebration_prompt: prompt } }];

const raw = $json.content[0].text;
const lines = raw.trim().split('\n');
let title = lines[0].replace(/\*\*/g, '').replace(/\*/g, '').replace(/#/g, '').trim();
if (title.length > 255) title = title.slice(0, 252) + '...';

let story_text = raw;
let scene_notes = '';
if (raw.includes('[SCENE NOTES]')) {
  story_text = raw.slice(0, raw.indexOf('[SCENE NOTES]')).trim();
  scene_notes = raw.slice(raw.indexOf('[SCENE NOTES]'));
}

return [{ json: { title, story_text, scene_notes, is_celebration: true, is_donation: false } }];

function tryGet(name) {
  try { const items = $(name).all(); return items.length ? items[items.length - 1].json : null; }
  catch (e) { return null; }
}

const story = tryGet('Parse Celebration Story') || tryGet('Inject Wallet Addresses') || tryGet('Parse Story');
const { selected_clan, clan, market_condition } = $('Select Clan').item.json;
const { story_count, has_override, override_id } = $('Build Story Prompt').item.json;

function esc(s) { return String(s ?? '').replace(/\\/g, '\\\\').replace(/'/g, "''"); }

return [{ json: {
  episode_number: story_count,
  selected_clan, clan_name: clan.name, territory: clan.territory,
  market_condition, has_override, override_id,
  title: story.title, story_text: story.story_text, scene_notes: story.scene_notes || '',
  is_celebration: !!story.is_celebration, is_donation: !!story.is_donation,
  title_sql: esc(story.title), story_text_sql: esc(story.story_text)
} }];

const GATES = {
  BTC:{gate1:100000,gate2:1000000,gate3:10000000}, ETH:{gate1:10000,gate2:100000,gate3:1000000},
  SOL:{gate1:1000,gate2:10000,gate3:100000}, XRP:{gate1:100,gate2:1000,gate3:10000},
  BNB:{gate1:10000,gate2:100000,gate3:1000000}, LTC:{gate1:1000,gate2:10000,gate3:100000},
  TON:{gate1:10,gate2:100,gate3:1000}, AVAX:{gate1:500,gate2:5000,gate3:50000},
  XLM:{gate1:5,gate2:50,gate3:500}, TRX:{gate1:1,gate2:10,gate3:100},
  ADA:{gate1:10,gate2:100,gate3:1000}, JASMY:{gate1:1,gate2:10,gate3:100},
  LINK:{gate1:1000,gate2:10000,gate3:100000}, UNI:{gate1:100,gate2:1000,gate3:10000},
  AAVE:{gate1:10000,gate2:100000,gate3:1000000}, INJ:{gate1:1000,gate2:10000,gate3:100000},
  PEPE:{gate1:1,gate2:10,gate3:100}, SHIB:{gate1:0.001,gate2:0.01,gate3:0.1},
  DOGE:{gate1:10,gate2:100,gate3:1000}, FLOKI:{gate1:1,gate2:10,gate3:100},
  NOT:{gate1:0.1,gate2:1,gate3:10}, BOME:{gate1:0.1,gate2:1,gate3:10}, BONK:{gate1:1,gate2:10,gate3:100}
};

const { prices, selected_clan } = $('Select Clan').item.json;
const allStatus = $('Get All Character Status').all().map(i => i.json);
const story_count = $('Build Story Prompt').item.json.story_count;
const story_id = $('Insert Story').item.json.insertId ?? $('Insert Story').item.json.insert_id ?? null;

function esc(s) { return String(s).replace(/'/g, "''"); }

const stmts = [];
for (const [ticker, data] of Object.entries(prices)) {
  stmts.push(`UPDATE character_status SET current_price = ${data.price}, last_updated = NOW() WHERE coin_ticker = '${esc(ticker)}'`);
}

for (const row of allStatus) {
  const ticker = row.coin_ticker;
  const gates = GATES[ticker];
  if (!gates || !prices[ticker]) continue;
  const gateKey = 'gate' + row.gate_number;
  const prevGateKey = 'gate' + (row.gate_number - 1);
  const gatePrice = gates[gateKey];
  const prevGatePrice = row.gate_number > 1 ? (gates[prevGateKey] || 0) : 0;
  if (!gatePrice) continue;
  const gap = gatePrice - prevGatePrice;
  const position = prices[ticker].price - prevGatePrice;
  let heaven = Math.ceil((position / gap) * 10);
  heaven = Math.max(1, Math.min(10, heaven));
  stmts.push(`UPDATE character_status SET heaven_number = ${heaven} WHERE coin_ticker = '${esc(ticker)}'`);
}

const nowSql = new Date().toISOString().slice(0,19).replace('T',' ');
stmts.push(`INSERT INTO site_settings (setting_key, setting_value) VALUES ('total_story_count', '${story_count}') ON DUPLICATE KEY UPDATE setting_value = '${story_count}'`);
stmts.push(`INSERT INTO site_settings (setting_key, setting_value) VALUES ('last_run', '${nowSql}') ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value)`);
stmts.push(`INSERT INTO clan_rotation (clan, story_id) VALUES ('${esc(selected_clan)}', ${story_id ?? 'NULL'})`);

return [{ json: { sql: stmts.join(';\n') + ';', story_id } }];

const clean = $('Finalize Story').item.json.story_text
  .replace(/\*\*/g, '')
  .replace(/\*/g, '')
  .replace(/\[.*?\]/g, '')
  .trim();
return [{ json: { narration_text: clean } }];

const { selected_clan, market_condition } = $('Finalize Story').item.json;
const { prices, clan } = $('Select Clan').item.json;

// Reusable clan background library convention — one image per clan x market condition.
// Pre-generate/place these once at /data/coinor/backgrounds/<clan>_<condition>.jpg
const background_path = `/data/coinor/backgrounds/${selected_clan}_${market_condition}.jpg`;

const overlayLines = clan.coins
  .filter(c => prices[c])
  .map(c => `${c} $${prices[c].price} (${prices[c].change_24h >= 0 ? '+' : ''}${prices[c].change_24h}%)`)
  .join('   |   ');

function escDraw(s) { return String(s).replace(/:/g, '\\:').replace(/'/g, "\\\\'"); }

return [{ json: {
  background_path,
  overlay_text: overlayLines,
  overlay_text_escaped: escDraw(overlayLines),
  audio_path: `/data/coinor/audio/episode_${$('Finalize Story').item.json.episode_number}.mp3`,
  output_path: `/data/coinor/output/episode_${$('Finalize Story').item.json.episode_number}.mp4`
} }];
